package com.frostsecurity.extreme.permissions;
import java.io.*; import java.nio.file.*; import java.util.*;
public final class PermissionAuditor { public record Finding(String rule,String severity,String line,String recommendation){} public static List<Finding> audit(Path file){List<Finding> out=new ArrayList<>();try{int n=0;for(String line:Files.readAllLines(file)){n++;String x=line.toLowerCase();if(x.contains("*"))out.add(new Finding("PERM-001","HIGH",n+": "+line.trim(),"Revise wildcard permissions e aplique menor privilégio."));if(x.contains("op")&&x.contains("true"))out.add(new Finding("PERM-002","MEDIUM",n+": "+line.trim(),"Confirme se a concessão administrativa é necessária."));}}catch(IOException e){out.add(new Finding("PERM-ERR","INFORMATIONAL",e.getMessage(),"Verifique o arquivo fornecido."));}return out;} }
